/** The bridge the runtime speaks through: generic protocol in, typed store out. */
class PartitionDriftStoreResolver(
    private val store: PartitionDriftStore,
    model: Model,
) : StateResolver {
    private val questions = PartitionDriftStoreQuestions(model)

    override fun begin(kind: WorkKind): UnitOfWork = store.begin(kind)

    override fun fetchByKeys(shape: String, keys: List<StoreKey>): List<Row> = when (shape) {
        "Note" -> store.notes(keys).map { it.toRow() }
        "LockNote" -> store.lockNotes(keys).map { it.toRow() }
        "UnlockNote" -> store.unlockNotes(keys).map { it.toRow() }
        "RenameText" -> store.renameTexts(keys).map { it.toRow() }
        "BareEdit" -> store.bareEdits(keys).map { it.toRow() }
        "BareEditRefusal" -> store.bareEditRefusals(keys).map { it.toRow() }
        "SafeEdit" -> store.safeEdits(keys).map { it.toRow() }
        "EditApplication" -> store.editApplications(keys).map { it.toRow() }
        "EditRefusal" -> store.editRefusals(keys).map { it.toRow() }
        "TransientEditRefusal" -> store.transientEditRefusals(keys).map { it.toRow() }
        else -> emptyList()
    }

    override fun fetchAll(shape: String): List<Row> = when (shape) {
        "Note" -> store.allNotes().map { it.toRow() }
        "LockNote" -> store.allLockNotes().map { it.toRow() }
        "UnlockNote" -> store.allUnlockNotes().map { it.toRow() }
        "RenameText" -> store.allRenameTexts().map { it.toRow() }
        "BareEdit" -> store.allBareEdits().map { it.toRow() }
        "BareEditRefusal" -> store.allBareEditRefusals().map { it.toRow() }
        "SafeEdit" -> store.allSafeEdits().map { it.toRow() }
        "EditApplication" -> store.allEditApplications().map { it.toRow() }
        "EditRefusal" -> store.allEditRefusals().map { it.toRow() }
        "TransientEditRefusal" -> store.allTransientEditRefusals().map { it.toRow() }
        else -> emptyList()
    }

    override fun fetchReferencingAny(shape: String, field: String, targets: List<Ref.Persisted>): List<Row> = when {
        shape == "LockNote" && field == "note" -> store.lockNotesByNotes(targets).map { it.toRow() }
        shape == "UnlockNote" && field == "note" -> store.unlockNotesByNotes(targets).map { it.toRow() }
        shape == "RenameText" && field == "note" -> store.renameTextsByNotes(targets).map { it.toRow() }
        shape == "BareEdit" && field == "note" -> store.bareEditsByNotes(targets).map { it.toRow() }
        shape == "BareEditRefusal" && field == "edit" -> store.bareEditRefusalsByEdits(targets).map { it.toRow() }
        shape == "SafeEdit" && field == "note" -> store.safeEditsByNotes(targets).map { it.toRow() }
        shape == "EditApplication" && field == "edit" -> store.editApplicationsByEdits(targets).map { it.toRow() }
        shape == "EditRefusal" && field == "edit" -> store.editRefusalsByEdits(targets).map { it.toRow() }
        shape == "TransientEditRefusal" && field == "note" -> store.transientEditRefusalsByNotes(targets).map { it.toRow() }
        else -> emptyList()
    }

    override fun fetchCandidates(shape: String, filter: QF): List<Row> {
        if (shape == "Note")
            questions.lockedNoteCandidates.match(filter)?.let { h -> return store.lockedNoteCandidates().map { it.toRow() } }
        if (shape == "BareEdit")
            questions.applicableBareEditCandidates.match(filter)?.let { h -> return store.applicableBareEditCandidates().map { it.toRow() } }
        if (shape == "BareEdit")
            questions.refusedBareEditCandidates.match(filter)?.let { h -> return store.refusedBareEditCandidates().map { it.toRow() } }
        if (shape == "SafeEdit")
            questions.unhandledSafeEditCandidates.match(filter)?.let { h -> return store.unhandledSafeEditCandidates().map { it.toRow() } }
        if (shape == "SafeEdit")
            questions.applicableSafeEditCandidates.match(filter)?.let { h -> return store.applicableSafeEditCandidates().map { it.toRow() } }
        if (shape == "SafeEdit")
            questions.refusedSafeEditCandidates.match(filter)?.let { h -> return store.refusedSafeEditCandidates().map { it.toRow() } }
        return fetchAll(shape) // unrecognized filters fall back to the scan floor
    }

    override fun fetchCaptures(instance: Ref.Persisted, refinement: String): Map<String, Any?>? = when (refinement) {
        else -> null
    }
}

